package ops

import (
	"strings"
	"time"

	"github.com/oklog/ulid/v2"
)

// OpType represents the type of knowledge operation.
type OpType string

const (
	OpAdd       OpType = "add"
	OpAmend     OpType = "amend"
	OpSupersede OpType = "supersede"
	OpRetire    OpType = "retire"
	OpMove      OpType = "move"
	OpSplit     OpType = "split"
)

// Provenance source constants.
const (
	SourceTurnNote      = "turn-note"
	SourceSidecar       = "sidecar"
	SourceSeed          = "seed"
	SourcePA            = "pa"
	SourceHuman         = "human"
	SourceConsolidation = "consolidation"
)

// Op represents a single knowledge operation targeting an entry by ID or dossier.
type Op struct {
	Type         OpType         `json:"type"`
	EntryID      string         `json:"entry_id,omitempty"`
	DossierScope string         `json:"dossier_scope,omitempty"`
	Timestamp    time.Time      `json:"timestamp"`
	Source       string         `json:"source"`
	SessionID    string         `json:"session_id,omitempty"`
	Fields       map[string]any `json:"fields,omitempty"`
}

// OpBatch represents an append-only batch of ops stored as a single file.
type OpBatch struct {
	Version   int       `json:"version"`
	Ops       []Op      `json:"ops"`
	CreatedAt time.Time `json:"created_at"`
	BatchID   string    `json:"batch_id"`
}

// NewBatchID generates a new ULID string for a batch.
func NewBatchID() string {
	return ulid.Make().String()
}

// NewBatchIDWithTime generates a new ULID string for a batch using the specified timestamp.
func NewBatchIDWithTime(t time.Time) string {
	return ulid.MustNew(ulid.Timestamp(t), ulid.DefaultEntropy()).String()
}

// NewEntryID creates a new entry ID with the given prefix and a ULID.
func NewEntryID(prefix string) string {
	prefix = strings.TrimSpace(prefix)
	if prefix != "" && !strings.HasSuffix(prefix, "-") {
		prefix += "-"
	}
	return prefix + ulid.Make().String()
}

// NewEntryIDWithTime creates a new entry ID with the given prefix and a ULID at time t.
func NewEntryIDWithTime(prefix string, t time.Time) string {
	prefix = strings.TrimSpace(prefix)
	if prefix != "" && !strings.HasSuffix(prefix, "-") {
		prefix += "-"
	}
	return prefix + ulid.MustNew(ulid.Timestamp(t), ulid.DefaultEntropy()).String()
}

// NewBatch creates an OpBatch initialized with version 1, current UTC time, and a generated batch ID.
func NewBatch(ops []Op) OpBatch {
	now := time.Now().UTC()
	return OpBatch{
		Version:   1,
		Ops:       ops,
		CreatedAt: now,
		BatchID:   NewBatchIDWithTime(now),
	}
}

package ops

import (
	"errors"
	"fmt"
	"strings"
)

// ValidateOp validates a single op against its type-specific rules.
func ValidateOp(op Op) error {
	switch op.Type {
	case OpAdd:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("add: entry_id is required")
		}
		if strings.TrimSpace(op.DossierScope) == "" {
			return errors.New("add: dossier_scope is required")
		}
		if op.Fields == nil {
			return errors.New("add: fields is required")
		}
		textVal, ok := op.Fields["text"]
		if !ok {
			return errors.New("add: fields.text is required")
		}
		textStr, ok := textVal.(string)
		if !ok || strings.TrimSpace(textStr) == "" {
			return errors.New("add: fields.text must be a non-empty string")
		}

	case OpAmend:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("amend: entry_id is required")
		}
		if op.Fields == nil || len(op.Fields) == 0 {
			return errors.New("amend: fields is required")
		}

	case OpSupersede:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("supersede: entry_id is required")
		}
		if op.Fields == nil {
			return errors.New("supersede: fields is required")
		}
		newIDVal, ok := op.Fields["new_entry_id"]
		if !ok {
			return errors.New("supersede: fields.new_entry_id is required")
		}
		newID, ok := newIDVal.(string)
		if !ok || strings.TrimSpace(newID) == "" {
			return errors.New("supersede: fields.new_entry_id must be a non-empty string")
		}
		textVal, ok := op.Fields["text"]
		if !ok {
			return errors.New("supersede: fields.text is required")
		}
		textStr, ok := textVal.(string)
		if !ok || strings.TrimSpace(textStr) == "" {
			return errors.New("supersede: fields.text must be a non-empty string")
		}

	case OpRetire:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("retire: entry_id is required")
		}
		if op.Fields == nil {
			return errors.New("retire: fields is required")
		}
		reasonVal, ok := op.Fields["reason"]
		if !ok {
			return errors.New("retire: fields.reason is required")
		}
		reasonStr, ok := reasonVal.(string)
		if !ok || strings.TrimSpace(reasonStr) == "" {
			return errors.New("retire: fields.reason must be a non-empty string")
		}

	case OpMove:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("move: entry_id is required")
		}
		if op.Fields == nil {
			return errors.New("move: fields is required")
		}
		toDossierVal, ok := op.Fields["to_dossier"]
		if !ok {
			return errors.New("move: fields.to_dossier is required")
		}
		toDossier, ok := toDossierVal.(string)
		if !ok || strings.TrimSpace(toDossier) == "" {
			return errors.New("move: fields.to_dossier must be a non-empty string")
		}

	case OpSplit:
		if strings.TrimSpace(op.DossierScope) == "" {
			return errors.New("split: dossier_scope is required")
		}
		if op.Fields == nil {
			return errors.New("split: fields is required")
		}

		rawNewDossiers, ok := op.Fields["new_dossiers"]
		if !ok {
			return errors.New("split: fields.new_dossiers is required")
		}
		var newDossiersCount int
		switch v := rawNewDossiers.(type) {
		case []string:
			newDossiersCount = len(v)
			for _, s := range v {
				if strings.TrimSpace(s) == "" {
					return errors.New("split: fields.new_dossiers must contain non-empty scope names")
				}
			}
		case []any:
			newDossiersCount = len(v)
			for _, item := range v {
				s, ok := item.(string)
				if !ok || strings.TrimSpace(s) == "" {
					return errors.New("split: fields.new_dossiers must contain non-empty string scope names")
				}
			}
		default:
			return errors.New("split: fields.new_dossiers must be a list of scope names")
		}
		if newDossiersCount == 0 {
			return errors.New("split: fields.new_dossiers cannot be empty")
		}

		rawEntryMoves, ok := op.Fields["entry_moves"]
		if !ok {
			return errors.New("split: fields.entry_moves is required")
		}
		var movesCount int
		switch v := rawEntryMoves.(type) {
		case map[string]string:
			movesCount = len(v)
			for k, s := range v {
				if strings.TrimSpace(k) == "" || strings.TrimSpace(s) == "" {
					return errors.New("split: fields.entry_moves contains empty entry ID or target scope")
				}
			}
		case map[string]any:
			movesCount = len(v)
			for k, val := range v {
				s, ok := val.(string)
				if !ok || strings.TrimSpace(k) == "" || strings.TrimSpace(s) == "" {
					return fmt.Errorf("split: fields.entry_moves[%q] must be a non-empty string target scope", k)
				}
			}
		default:
			return errors.New("split: fields.entry_moves must be a map of entry ID to scope name")
		}
		if movesCount == 0 {
			return errors.New("split: fields.entry_moves cannot be empty")
		}

	case "":
		return errors.New("op type is required")

	default:
		return fmt.Errorf("unknown op type %q", op.Type)
	}

	return nil
}

// ValidateBatch validates an entire OpBatch.
func ValidateBatch(batch OpBatch) error {
	if batch.Version < 1 {
		return errors.New("batch version must be >= 1")
	}
	if strings.TrimSpace(batch.BatchID) == "" {
		return errors.New("batch_id is required")
	}
	if batch.CreatedAt.IsZero() {
		return errors.New("created_at is required")
	}
	if len(batch.Ops) == 0 {
		return errors.New("batch must contain at least one op")
	}
	for i, op := range batch.Ops {
		if err := ValidateOp(op); err != nil {
			return fmt.Errorf("op[%d]: %w", i, err)
		}
	}
	return nil
}

package ops

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// Writer writes OpBatch files into the ops log directory.
type Writer struct {
	baseDir string
}

// NewWriter creates a new Writer for the specified base directory.
func NewWriter(baseDir string) *Writer {
	return &Writer{
		baseDir: baseDir,
	}
}

// Write writes the batch as indented JSON to .memory/ops/<yyyy-mm>/<batch-id>.json,
// creating the month directory if needed.
func (w *Writer) Write(batch OpBatch) error {
	if err := ValidateBatch(batch); err != nil {
		return fmt.Errorf("validate batch: %w", err)
	}

	month := batch.CreatedAt.UTC().Format("2006-01")
	monthDir := filepath.Join(w.baseDir, month)
	if err := os.MkdirAll(monthDir, 0o755); err != nil {
		return fmt.Errorf("create month directory %s: %w", monthDir, err)
	}

	filePath := filepath.Join(monthDir, batch.BatchID+".json")
	data, err := json.MarshalIndent(batch, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal batch %s: %w", batch.BatchID, err)
	}
	data = append(data, '\n')

	if err := os.WriteFile(filePath, data, 0o644); err != nil {
		return fmt.Errorf("write batch file %s: %w", filePath, err)
	}

	return nil
}

package ops

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// Reader reads and validates OpBatch files from the ops log directory.
type Reader struct {
	baseDir string
	gitDir  string
}

// NewReader creates a new Reader for the specified base directory.
func NewReader(baseDir string) *Reader {
	return &Reader{
		baseDir: baseDir,
	}
}

// WithGitDir configures the git directory used for resolving commit timestamps.
func (r *Reader) WithGitDir(gitDir string) *Reader {
	r.gitDir = gitDir
	return r
}

// ReadBatch reads and validates a single batch file from path.
// If path is not absolute and does not exist relative to the working directory,
// it is checked relative to r.baseDir.
func (r *Reader) ReadBatch(path string) (*OpBatch, error) {
	targetPath := path
	if !filepath.IsAbs(targetPath) {
		if _, err := os.Stat(targetPath); errors.Is(err, os.ErrNotExist) && r.baseDir != "" {
			targetPath = filepath.Join(r.baseDir, path)
		}
	}

	data, err := os.ReadFile(targetPath)
	if err != nil {
		return nil, fmt.Errorf("read batch file: %w", err)
	}

	var batch OpBatch
	if err := json.Unmarshal(data, &batch); err != nil {
		return nil, fmt.Errorf("unmarshal batch json: %w", err)
	}

	if err := ValidateBatch(batch); err != nil {
		return nil, fmt.Errorf("invalid batch in %s: %w", targetPath, err)
	}

	return &batch, nil
}

package ops

import (
	"context"
	"errors"
	"fmt"
	"io"
	"iter"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// Iterator provides iteration over op batches.
type Iterator struct {
	reader       *Reader
	ctx          context.Context
	afterBatchID string
	beforeTime   *time.Time
	pullNext     func() (*OpBatch, error, bool)
	pullStop     func()
}

// NewIterator creates a new Iterator.
func NewIterator(r *Reader, ctx context.Context) *Iterator {
	if ctx == nil {
		ctx = context.Background()
	}
	return &Iterator{
		reader: r,
		ctx:    ctx,
	}
}

// Seq returns the iter.Seq2 sequence for this iterator.
func (it *Iterator) Seq() iter.Seq2[*OpBatch, error] {
	return it.reader.iterateInternal(it.ctx, it.afterBatchID, it.beforeTime)
}

// Next pulls the next batch from the iterator. Returns io.EOF when iteration is done.
func (it *Iterator) Next() (*OpBatch, error) {
	if it.pullNext == nil {
		next, stop := iter.Pull2(it.Seq())
		it.pullNext = next
		it.pullStop = stop
	}
	batch, err, ok := it.pullNext()
	if !ok {
		return nil, io.EOF
	}
	return batch, err
}

// Close terminates any active pull iteration and frees associated resources.
func (it *Iterator) Close() {
	if it.pullStop != nil {
		it.pullStop()
		it.pullNext = nil
		it.pullStop = nil
	}
}

// Iterate yields batches in ULID order (which is chronological).
// It walks month directories in order, then files within each month in ULID order.
func (r *Reader) Iterate(ctx context.Context) iter.Seq2[*OpBatch, error] {
	if ctx == nil {
		ctx = context.Background()
	}
	it := &Iterator{reader: r, ctx: ctx}
	return it.Seq()
}

// IterateAfter yields only batches strictly after the given batch ID.
func (r *Reader) IterateAfter(ctx context.Context, afterBatchID string) iter.Seq2[*OpBatch, error] {
	if ctx == nil {
		ctx = context.Background()
	}
	it := &Iterator{reader: r, ctx: ctx, afterBatchID: afterBatchID}
	return it.Seq()
}

// IterateBefore yields only batches whose CreatedAt is before the given commit's timestamp.
// The beforeCommit is a git commit reference; its timestamp is resolved via git log -1 --format=%cI <commit>.
func (r *Reader) IterateBefore(ctx context.Context, beforeCommit string) iter.Seq2[*OpBatch, error] {
	if ctx == nil {
		ctx = context.Background()
	}
	return func(yield func(*OpBatch, error) bool) {
		cutoff, err := r.resolveCommitTime(ctx, beforeCommit)
		if err != nil {
			yield(nil, err)
			return
		}
		for batch, bErr := range r.IterateBeforeTime(ctx, cutoff) {
			if !yield(batch, bErr) {
				return
			}
		}
	}
}

// IterateBeforeTime yields only batches whose CreatedAt is before the specified cutoff timestamp.
func (r *Reader) IterateBeforeTime(ctx context.Context, cutoff time.Time) iter.Seq2[*OpBatch, error] {
	if ctx == nil {
		ctx = context.Background()
	}
	it := &Iterator{reader: r, ctx: ctx, beforeTime: &cutoff}
	return it.Seq()
}

func (r *Reader) iterateInternal(ctx context.Context, afterBatchID string, beforeTime *time.Time) iter.Seq2[*OpBatch, error] {
	return func(yield func(*OpBatch, error) bool) {
		if ctx == nil {
			ctx = context.Background()
		}

		if err := ctx.Err(); err != nil {
			yield(nil, err)
			return
		}

		entries, err := os.ReadDir(r.baseDir)
		if errors.Is(err, os.ErrNotExist) {
			return
		}
		if err != nil {
			yield(nil, fmt.Errorf("read ops base dir %s: %w", r.baseDir, err))
			return
		}

		var monthDirs []string
		for _, entry := range entries {
			if !entry.IsDir() {
				continue
			}
			name := entry.Name()
			if _, parseErr := time.Parse("2006-01", name); parseErr == nil {
				monthDirs = append(monthDirs, name)
			}
		}
		sort.Strings(monthDirs)

		seenAfter := (afterBatchID == "")

		for _, monthDir := range monthDirs {
			if err := ctx.Err(); err != nil {
				yield(nil, err)
				return
			}

			monthPath := filepath.Join(r.baseDir, monthDir)
			fileEntries, err := os.ReadDir(monthPath)
			if err != nil {
				if !yield(nil, fmt.Errorf("read month dir %s: %w", monthPath, err)) {
					return
				}
				continue
			}

			var jsonFiles []os.DirEntry
			for _, f := range fileEntries {
				if !f.IsDir() && strings.HasSuffix(f.Name(), ".json") {
					jsonFiles = append(jsonFiles, f)
				}
			}

			sort.Slice(jsonFiles, func(i, j int) bool {
				return jsonFiles[i].Name() < jsonFiles[j].Name()
			})

			for _, f := range jsonFiles {
				if err := ctx.Err(); err != nil {
					yield(nil, err)
					return
				}

				filePath := filepath.Join(monthPath, f.Name())
				batch, err := r.ReadBatch(filePath)
				if err != nil {
					if !yield(nil, fmt.Errorf("read batch %s: %w", filePath, err)) {
						return
					}
					continue
				}

				if !seenAfter {
					if batch.BatchID == afterBatchID {
						seenAfter = true
						continue
					}
					if strings.ToUpper(batch.BatchID) > strings.ToUpper(afterBatchID) {
						seenAfter = true
					} else {
						continue
					}
				}

				if beforeTime != nil && !batch.CreatedAt.UTC().Before(beforeTime.UTC()) {
					continue
				}

				if !yield(batch, nil) {
					return
				}
			}
		}
	}
}

func (r *Reader) resolveCommitTime(ctx context.Context, beforeCommit string) (time.Time, error) {
	if strings.TrimSpace(beforeCommit) == "" {
		return time.Time{}, errors.New("beforeCommit cannot be empty")
	}

	dir := r.gitDir
	if dir == "" {
		dir = r.baseDir
	}

	var cmd *exec.Cmd
	if dir != "" {
		cmd = exec.CommandContext(ctx, "git", "-C", dir, "log", "-1", "--format=%cI", beforeCommit)
	} else {
		cmd = exec.CommandContext(ctx, "git", "log", "-1", "--format=%cI", beforeCommit)
	}

	out, err := cmd.CombinedOutput()
	if err != nil {
		if dir != "." && dir != "" {
			cmd2 := exec.CommandContext(ctx, "git", "log", "-1", "--format=%cI", beforeCommit)
			if out2, err2 := cmd2.CombinedOutput(); err2 == nil {
				out = out2
				err = nil
			}
		}
	}

	if err != nil {
		return time.Time{}, fmt.Errorf("git log commit %q: %w (output: %s)", beforeCommit, err, strings.TrimSpace(string(out)))
	}

	raw := strings.TrimSpace(string(out))
	if raw == "" {
		return time.Time{}, fmt.Errorf("no commit timestamp found for %q", beforeCommit)
	}

	t, err := time.Parse(time.RFC3339, raw)
	if err != nil {
		return time.Time{}, fmt.Errorf("parse commit timestamp %q: %w", raw, err)
	}

	return t, nil
}

package ops

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// MigrateV1Events moves the v1 events directory to the archive directory if it exists.
// If eventsDir does not exist, it is a no-op and returns nil.
func MigrateV1Events(eventsDir, archiveDir string) error {
	info, err := os.Stat(eventsDir)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("stat events dir: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("events path %s is not a directory", eventsDir)
	}

	cleanEvents := filepath.Clean(eventsDir)
	cleanArchive := filepath.Clean(archiveDir)
	if cleanEvents == cleanArchive {
		return nil
	}

	if err := os.MkdirAll(filepath.Dir(cleanArchive), 0o755); err != nil {
		return fmt.Errorf("create archive parent dir: %w", err)
	}

	// Try direct atomic rename first
	if err := os.Rename(cleanEvents, cleanArchive); err == nil {
		return nil
	}

	// If destination already exists or rename fails across devices, move contents recursively
	if err := moveDirContents(cleanEvents, cleanArchive); err != nil {
		return fmt.Errorf("migrate events from %s to %s: %w", cleanEvents, cleanArchive, err)
	}

	return os.RemoveAll(cleanEvents)
}

func moveDirContents(srcDir, dstDir string) error {
	if err := os.MkdirAll(dstDir, 0o755); err != nil {
		return err
	}
	entries, err := os.ReadDir(srcDir)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		srcPath := filepath.Join(srcDir, entry.Name())
		dstPath := filepath.Join(dstDir, entry.Name())
		if entry.IsDir() {
			if err := moveDirContents(srcPath, dstPath); err != nil {
				return err
			}
		} else {
			if err := os.Rename(srcPath, dstPath); err != nil {
				if err := copyFile(srcPath, dstPath); err != nil {
					return err
				}
				if err := os.Remove(srcPath); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()

	if _, err := io.Copy(out, in); err != nil {
		return err
	}
	return out.Sync()
