					"entry_moves": map[string]string{
						"inv-1": "core/parser",
					},
				},
			},
			wantErr: true,
			errMsg:  "fields.new_dossiers is required",
		},
		{
			name: "split: empty new_dossiers",
			op: Op{
				Type:         OpSplit,
				DossierScope: "core/monolith",
				Fields: map[string]any{
